cat > "$TMPDIR/anomaly.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-LPJ4Iu/project/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  for (const width of [1280, 1024, 768, 390]) {
    const ctx = await b.newContext({ viewport: { width, height: 900 } });
    const page = await ctx.newPage();
    for (const p of ['index','products','pricing','orders','about','contact']) {
      await page.goto(`http://127.0.0.1:4183/${p}.html`, { waitUntil: 'networkidle' });
      const issues = await page.evaluate(() => {
        const out = [];
        const vw = document.documentElement.clientWidth;
        for (const el of document.querySelectorAll('body *')) {
          const cs = getComputedStyle(el);
          const r = el.getBoundingClientRect();
          if (r.width === 0 || r.height === 0) continue;
          if (el.tagName === 'TABLE' || el.closest('.table-wrap')) continue;
          if (el.scrollWidth > el.clientWidth + 1 && cs.overflowX !== 'auto' && cs.overflowX !== 'scroll' && cs.display !== 'inline' && el.children.length === 0) {
            out.push({type:'clipped', tag:el.tagName, cls:String(el.className).slice(0,40), sw:el.scrollWidth, cw:el.clientWidth, text:(el.textContent||'').trim().slice(0,40)});
          }
          if (r.right > vw + 1 && cs.position !== 'fixed') out.push({type:'offscreen', tag:el.tagName, cls:String(el.className).slice(0,40), right:Math.round(r.right), vw});
        }
        // images distorted
        for (const img of document.images) {
          if (img.naturalWidth && img.width) {
            const nr = img.naturalWidth/img.naturalHeight, ar = img.width/img.height;
            if (Math.abs(nr-ar)/nr > 0.02) out.push({type:'distorted', src:img.getAttribute('src'), ar:ar.toFixed(2), nr:nr.toFixed(2)});
          }
        }
        return out;
      });
      if (issues.length) console.log(width, p, JSON.stringify(issues));
    }
    await ctx.close();
  }
  await b.close();
})();
EOF
