export PORT=45477 && node server.js >/dev/null 2>&1 & SRV=$!; sleep 1.2; mkdir -p "$TMPDIR/shots"; cat > "$TMPDIR/shots/cap.js" <<'JS'
const { chromium } = require('@playwright/test');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const pages = ['index','products','pricing','orders','about','contact'];
  for (const name of pages) {
    await page.goto(`http://127.0.0.1:45477/${name}.html`, { waitUntil: 'networkidle' });
    await page.evaluate(() => document.fonts.ready);
    await page.screenshot({ path: `${process.env.TMPDIR}/shots/${name}.png`, fullPage: true });
    console.log(name, await page.evaluate(() => document.documentElement.scrollHeight));
  }
  await browser.close();
})();
