const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 390, height: 844 } });
  await p.goto('http://127.0.0.1:45492/index.html', { waitUntil: 'networkidle' });
  const r = await p.evaluate(() => {
    const t = document.querySelector('.nav-toggle').getBoundingClientRect();
    const bars = [...document.querySelectorAll('.nav-toggle-bar')].map(e => {
      const b = e.getBoundingClientRect();
      return { top: +(b.top - t.top).toFixed(2), h: +b.height.toFixed(2) };
    });
    return { toggle: { h: t.height, w: t.width }, bars };
  });
  console.log(JSON.stringify(r, null, 1));
  const buf = await p.locator('.nav-toggle').screenshot();
  require('fs').writeFileSync(process.env.TMPDIR + '/shots/toggle.png', buf);
  await b.close();
})();
